import {createAttackSlash,targetEffectAngle,slashElapsed} from './attack-motion-fx.mjs';
import {sequences,frameAt,renderBounds} from './sequence-art.mjs';
import {duration,hitTime,routes,sample,displacement} from './attack-motion-model.mjs';
const $=id=>document.getElementById(id), images={},units=[];
const drawAttackSlash=createAttackSlash($('attack-slash'));
let mode='short',route='far',rig='temple_swordsman',time=0,last=0,playing=false,ready=false,queue=[];
function row(id,enemy,rear){for(let i=0;i<3;i++){const slot=document.createElement('div');slot.className='slot '+(enemy?'enemy':'player');$(id).append(slot);if(rear){slot.classList.add('empty');slot.textContent='◇';continue;}slot.innerHTML=`<div class="card"><span class="slot-label">${enemy?'敌':'我'} ${enemy?3-i:i+1}</span><div class="sprite"><canvas width="192" height="192"></canvas></div><div class="stats"><span>⚔ 4</span><span class="health">♥ 12/12</span></div><div class="hp"><i></i></div></div>`;units.push({slot,card:slot.querySelector('.card'),sprite:slot.querySelector('.sprite'),canvas:slot.querySelector('canvas'),enemy,index:i,rig:enemy?'temple_knight':i===0?rig:'temple_swordsman'});}}
row('enemy-rear',true,true);row('enemy-front',true,false);row('player-front',false,false);row('player-rear',false,true);
function center(el,board){const r=el.getBoundingClientRect();return {x:r.left+r.width/2-board.left,y:r.top+r.height/2-board.top};}
function drawSprite(u,active){const motion=active&&time>=.18&&time<.94?'attack':'idle';const b=renderBounds[u.rig],ctx=u.canvas.getContext('2d'),scale=192/Math.max(b.width,b.height);ctx.clearRect(0,0,192,192);ctx.imageSmoothingEnabled=false;ctx.save();if(u.enemy){ctx.translate(192,0);ctx.scale(-1,1);}ctx.drawImage(images[u.rig][motion],frameAt(motion,motion==='attack'?(time-.18)*1000:time*1000,u.rig)*192+b.x,b.y,b.width,b.height,(192-b.width*scale)/2,(192-b.height*scale)/2,b.width*scale,b.height*scale);ctx.restore();}
function render(){if(!ready)return;const r=routes[route],s=sample(time),attacker=units.find(u=>!u.enemy&&u.index===r.from),target=units.find(u=>u.enemy&&u.index===r.to),board=$('board').getBoundingClientRect();for(const u of units){u.card.style.transform='';u.sprite.style.transform='';u.slot.style.zIndex='';u.card.classList.remove('active','target');u.card.style.opacity='1';u.card.querySelector('.health').textContent='♥ 12/12';u.card.querySelector('.hp i').style.width='100%';u.rig=!u.enemy&&u.index===0?rig:u.enemy?'temple_knight':'temple_swordsman';drawSprite(u,u===attacker);}
const from=center(attacker.slot,board),to=center(target.slot,board),height=attacker.slot.getBoundingClientRect().height,delta=displacement(from,to,mode,height),d=Math.hypot(to.x-from.x,to.y-from.y)||1;const active=time<.94;attacker.card.classList.toggle('active',active);target.card.classList.toggle('target',active);attacker.slot.style.zIndex='10';target.slot.style.zIndex='5';(mode==='card'?attacker.card:attacker.sprite).style.transform=`translate(${delta.x*s.travel}px,${delta.y*s.travel}px)`;target.card.style.transform=`translate(${(to.x-from.x)/d*9*s.recoil}px,${(to.y-from.y)/d*9*s.recoil}px)`;if(s.hit){target.card.querySelector('.health').textContent='♥ 8/12';target.card.querySelector('.hp i').style.width='66.6667%';}
drawAttackSlash(slashElapsed(time,hitTime),center(target.sprite,board),targetEffectAngle(from,to),Math.max(.65,Math.min(1.2,height/130)),$('show-fx').checked&&mode==='short');
$('line').setAttribute('d',`M${from.x},${from.y} L${to.x},${to.y}`);$('route-line').style.opacity=$('guide').checked&&time<hitTime?'1':'0';$('impact').style.cssText=`left:${to.x}px;top:${to.y}px;opacity:${mode==='short'?0:s.flash};transform:translate(-50%,-50%) scale(${1.5-s.flash*.5})`;$('damage').style.cssText=`left:${to.x}px;top:${to.y-height*.3-20*Math.min(1,Math.max(0,(time-hitTime)/.5))}px;opacity:${time>=hitTime&&time<1?1:0};transform:translate(-50%,-50%)`;$('phase').textContent=s.phase;$('time').textContent=time.toFixed(2)+' s';$('timeline').value=time;$('caption').textContent=`我方左侧 → 对手${['左侧','中间','右侧'][r.to]} · ${r.label}`;$('pause').textContent=playing?'暂停':'继续';}
function restart(){time=0;last=0;playing=true;render();}
for(const button of document.querySelectorAll('[data-mode]'))button.onclick=()=>{mode=button.dataset.mode;for(const b of document.querySelectorAll('[data-mode]'))b.setAttribute('aria-pressed',String(b===button));$('mode-title').textContent=button.textContent;$('description').textContent=mode==='short'?'A：角色短突进；PixelFX 剑刃斩击在目标身上按攻击方向旋转，角色自身不旋转。':'B：整张角色卡牌接近目标后冲撞，随后回到原格位。';queue=[];restart();};
$('route').onchange=()=>{route=$('route').value;queue=[];restart();};$('actor').onchange=()=>{rig=$('actor').value;restart();};$('play').onclick=()=>{queue=[];restart();};$('pause').onclick=()=>{playing=!playing;if(playing&&time>=duration)time=0;last=0;render();};$('timeline').oninput=()=>{playing=false;queue=[];time=Number($('timeline').value);render();};$('guide').onchange=render;$('show-fx').onchange=render;$('sequence').onclick=()=>{queue=['near','far'];route='straight';$('route').value=route;restart();};
function tick(now){if(ready&&playing&&!document.hidden){if(last)time=Math.min(duration,time+(now-last)/1000*Number($('speed').value));if(time>=duration){if(queue.length){route=queue.shift();$('route').value=route;time=0;}else playing=false;}render();}last=now;requestAnimationFrame(tick);}new ResizeObserver(()=>render()).observe($('board'));document.addEventListener('visibilitychange',()=>{last=0;});
Promise.all(['temple_knight','temple_swordsman'].flatMap(key=>{images[key]={};return ['idle','attack'].map(motion=>new Promise((resolve,reject)=>{const img=new Image();images[key][motion]=img;img.onload=resolve;img.onerror=()=>reject(new Error('角色图集加载失败，请刷新重试'));img.src=new URL(`../assets/characters/${sequences[key].folder}/${motion}-sheet.png`,import.meta.url);}));})).then(()=>{ready=true;for(const id of ['play','pause','sequence','timeline'])$(id).disabled=false;render();requestAnimationFrame(tick);}).catch(error=>{$('error').hidden=false;$('error').textContent=error.message;$('phase').textContent='加载失败';});
